# Grammaire lituanienne, expliquée dans les autres langues d'interface.
T = {
'alphabet': {
 'es': ('El alfabeto y la pronunciación', "32 letras, con signos propios: ą ę į ų (antes nasales, hoy vocales largas), ė, ū, č š ž, y. La «j» suena como la y de «yo».\nHay dos acentos tonales (no se escriben) y un acento de palabra móvil; la longitud de las vocales distingue palabras. Cada letra se lee siempre igual.", ['Buenos días.']),
 'de': ('Alphabet und Aussprache', "32 Buchstaben, darunter eigene: ą ę į ų (früher nasal, heute lange Vokale), ė, ū, č š ž, y. „j“ wird wie im Deutschen gesprochen.\nEs gibt zwei Tonakzente (nicht geschrieben) und eine bewegliche Wortbetonung; die Vokallänge unterscheidet Wörter. Jeder Buchstabe wird immer gleich gelesen.", ['Guten Morgen.']),
 'it': ("L'alfabeto e la pronuncia", "32 lettere, con segni propri: ą ę į ų (un tempo nasali, oggi vocali lunghe), ė, ū, č š ž, y. La «j» si legge come la i di «ieri».\nCi sono due accenti tonali (non scritti) e un accento di parola mobile; la lunghezza delle vocali distingue le parole. Ogni lettera si legge sempre allo stesso modo.", ['Buongiorno.']),
 'pt': ('O alfabeto e a pronúncia', "32 letras, com sinais próprios: ą ę į ų (antes nasais, hoje vogais longas), ė, ū, č š ž, y. O «j» soa como o i de «iate».\nHá dois acentos tonais (não escritos) e um acento de palavra móvel; a duração das vogais distingue palavras. Cada letra lê-se sempre da mesma forma.", ['Bom dia.']),
 'ja': ('アルファベットと発音', "32文字で、独自の文字があります：ą ę į ų（かつての鼻母音、いまは長母音）、ė、ū、č š ž、y。「j」は「ヤ行」の音です。\n書かれない二種類の声調アクセントと移動する語アクセントがあり、母音の長短で意味が変わります。どの文字も常に同じように読みます。", ['おはようございます。']),
 'zh': ('字母与发音', "共 32 个字母，包括特有字母：ą ę į ų（原为鼻元音，现为长元音），ė，ū，č š ž，y。「j」读如汉语拼音的 y。\n有两种不写出的声调重音，词重音位置可变；元音长短可以区分词义。每个字母的读音始终不变。", ['早上好。']),
 'ko': ('알파벳과 발음', "32개 글자이며 고유한 글자가 있습니다: ą ę į ų(예전엔 비모음, 지금은 장모음), ė, ū, č š ž, y. 「j」는 영어 y처럼 발음합니다.\n표기되지 않는 두 가지 성조 악센트와 위치가 바뀌는 강세가 있고, 모음의 길이로 단어가 구별됩니다. 각 글자는 늘 같은 소리로 읽습니다.", ['좋은 아침입니다.']),
 'tl': ('Ang alpabeto at pagbigkas', "32 titik, kasama ang mga natatangi: ą ę į ų (dating pailong, ngayon mahahabang patinig), ė, ū, č š ž, y. Ang «j» ay parang y ng «yelo».\nMay dalawang tono ng diin (hindi isinusulat) at gumagalaw na diin ng salita; nagpapaiba ng salita ang haba ng patinig. Laging pareho ang basa ng bawat titik.", ['Magandang umaga.']),
},
'cas': {
 'es': ('Los siete casos', "El sustantivo se declina según su función: nominativo (sujeto: vyras), genitivo (de: vyro), dativo (a, para: vyrui), acusativo (objeto directo: vyrą), instrumental (con, por: vyru), locativo (en: vyre), vocativo (llamada: vyre!).\nEl caso se ve en la terminación, que depende del género (masculino, femenino) y de la clase del sustantivo. No hay artículo.", ['Veo al hombre.', 'El libro está sobre la mesa.']),
 'de': ('Die sieben Fälle', "Das Nomen wird nach seiner Funktion dekliniert: Nominativ (Subjekt: vyras), Genitiv (von: vyro), Dativ (wem: vyrui), Akkusativ (direktes Objekt: vyrą), Instrumental (mit, durch: vyru), Lokativ (in: vyre), Vokativ (Anrede: vyre!).\nDer Fall zeigt sich an der Endung, die vom Genus (maskulin, feminin) und der Klasse des Nomens abhängt. Keine Artikel.", ['Ich sehe den Mann.', 'Das Buch liegt auf dem Tisch.']),
 'it': ('I sette casi', "Il nome si declina secondo la funzione: nominativo (soggetto: vyras), genitivo (di: vyro), dativo (a: vyrui), accusativo (complemento oggetto: vyrą), strumentale (con, per mezzo di: vyru), locativo (in: vyre), vocativo (richiamo: vyre!).\nIl caso si legge nella desinenza, che dipende dal genere (maschile, femminile) e dalla classe del nome. Niente articoli.", ["Vedo l'uomo.", 'Il libro è sul tavolo.']),
 'pt': ('Os sete casos', "O substantivo declina-se conforme a função: nominativo (sujeito: vyras), genitivo (de: vyro), dativo (a, para: vyrui), acusativo (objeto direto: vyrą), instrumental (com, por: vyru), locativo (em: vyre), vocativo (chamamento: vyre!).\nO caso vê-se na terminação, que depende do gênero (masculino, feminino) e da classe do substantivo. Não há artigo.", ['Vejo o homem.', 'O livro está sobre a mesa.']),
 'ja': ('七つの格', "名詞は役割に応じて格変化します：主格（主語：vyras）、属格（〜の：vyro）、与格（〜に：vyrui）、対格（直接目的語：vyrą）、具格（〜で・〜によって：vyru）、処格（〜の中で：vyre）、呼格（呼びかけ：vyre!）。\n格は語尾でわかり、語尾は性（男性・女性）と名詞の型によって決まります。冠詞はありません。", ['私はその男の人を見ます。', '本は机の上にあります。']),
 'zh': ('七个格', "名词按其作用变格：主格（主语：vyras），属格（……的：vyro），与格（给：vyrui），宾格（直接宾语：vyrą），工具格（用、通过：vyru），位格（在……里：vyre），呼格（称呼：vyre!）。\n格由词尾表示，词尾取决于性（阳性、阴性）和名词类别。没有冠词。", ['我看见那个男人。', '书在桌子上。']),
 'ko': ('일곱 가지 격', "명사는 문장 속 역할에 따라 형태가 바뀝니다: 주격(주어: vyras), 속격(~의: vyro), 여격(~에게: vyrui), 대격(목적어: vyrą), 도구격(~로, ~와 함께: vyru), 처격(~에서: vyre), 호격(부를 때: vyre!).\n격은 어미로 드러나며, 어미는 성(남성, 여성)과 명사 부류에 따라 다릅니다. 관사가 없습니다.", ['나는 그 남자를 봐요.', '책이 탁자 위에 있어요.']),
 'tl': ('Ang pitong kaukulan', "Nagbabago ang pangngalan ayon sa gamit: nominatibo (simuno: vyras), henitibo (ng: vyro), datibo (para kay: vyrui), akusatibo (tuwirang layon: vyrą), instrumental (kasama, gamit: vyru), lokatibo (sa loob: vyre), bokatibo (pagtawag: vyre!).\nMakikita ang kaukulan sa hulapi, na nakadepende sa kasarian (panlalaki, pambabae) at uri ng pangngalan. Walang pantukoy.", ['Nakikita ko ang lalaki.', 'Nasa mesa ang libro.']),
},
'buti': {
 'es': ('El verbo «būti» (ser, estar)', "Presente: esu, esi, yra, esame, esate, yra. Pasado: buvau, buvai, buvo, buvome, buvote, buvo. Futuro: būsiu, būsi, bus, būsime, būsite, bus.\nEn tercera persona se usa yra (a menudo se omite: Jis gydytojas). Posesión: Aš turiu (tengo, del verbo turėti); o Man yra… (para mí hay…).\nAtributo en nominativo: Jis yra studentas.", ['Soy estudiante.', 'Él está en casa.']),
 'de': ('Das Verb „būti“ (sein)', "Präsens: esu, esi, yra, esame, esate, yra. Vergangenheit: buvau, buvai, buvo, buvome, buvote, buvo. Futur: būsiu, būsi, bus, būsime, būsite, bus.\nIn der 3. Person steht yra (oft weggelassen: Jis gydytojas). Besitz: Aš turiu (ich habe, von turėti); oder Man yra… (mir ist…).\nPrädikat im Nominativ: Jis yra studentas.", ['Ich bin Student.', 'Er ist zu Hause.']),
 'it': ('Il verbo «būti» (essere)', "Presente: esu, esi, yra, esame, esate, yra. Passato: buvau, buvai, buvo, buvome, buvote, buvo. Futuro: būsiu, būsi, bus, būsime, būsite, bus.\nAlla 3ª persona si usa yra (spesso omesso: Jis gydytojas). Possesso: Aš turiu (ho, dal verbo turėti); oppure Man yra… (a me c'è…).\nPredicato al nominativo: Jis yra studentas.", ['Sono uno studente.', 'Lui è a casa.']),
 'pt': ('O verbo «būti» (ser, estar)', "Presente: esu, esi, yra, esame, esate, yra. Passado: buvau, buvai, buvo, buvome, buvote, buvo. Futuro: būsiu, būsi, bus, būsime, būsite, bus.\nNa 3ª pessoa usa-se yra (muitas vezes omitido: Jis gydytojas). Posse: Aš turiu (tenho, do verbo turėti); ou Man yra… (para mim há…).\nPredicativo no nominativo: Jis yra studentas.", ['Sou estudante.', 'Ele está em casa.']),
 'ja': ('動詞 «būti»（〜である・いる）', "現在：esu, esi, yra, esame, esate, yra。過去：buvau, buvai, buvo, buvome, buvote, buvo。未来：būsiu, būsi, bus, būsime, būsite, bus。\n3人称では yra を使います（しばしば省略：Jis gydytojas）。所有：Aš turiu（持っている、turėti から）、または Man yra…（私には〜がある）。\n述語は主格：Jis yra studentas。", ['私は学生です。', '彼は家にいます。']),
 'zh': ('动词 «būti»（是、在）', "现在时：esu, esi, yra, esame, esate, yra。过去时：buvau, buvai, buvo, buvome, buvote, buvo。将来时：būsiu, būsi, bus, būsime, būsite, bus。\n第三人称用 yra（常省略：Jis gydytojas）。拥有：Aš turiu（我有，来自 turėti）；或 Man yra…（我有……）。\n表语用主格：Jis yra studentas。", ['我是学生。', '他在家。']),
 'ko': ('동사 «būti»(이다, 있다)', "현재: esu, esi, yra, esame, esate, yra. 과거: buvau, buvai, buvo, buvome, buvote, buvo. 미래: būsiu, būsi, bus, būsime, būsite, bus.\n3인칭에서는 yra를 쓰며 자주 생략합니다(Jis gydytojas). 소유: Aš turiu(나는 가지고 있다, turėti에서), 또는 Man yra…(나에게 ~이 있다).\n보어는 주격: Jis yra studentas.", ['저는 학생이에요.', '그는 집에 있어요.']),
 'tl': ('Ang pandiwang «būti» (maging, naroon)', "Kasalukuyan: esu, esi, yra, esame, esate, yra. Nakaraan: buvau, buvai, buvo, buvome, buvote, buvo. Hinaharap: būsiu, būsi, bus, būsime, būsite, bus.\nSa ikatlong panauhan ginagamit ang yra (madalas inaalis: Jis gydytojas). Pagmamay-ari: Aš turiu (mayroon ako, mula sa turėti); o Man yra… (sa akin ay may…).\nPanaguri sa nominatibo: Jis yra studentas.", ['Estudyante ako.', 'Nasa bahay siya.']),
},
'present': {
 'es': ('El presente', "Tres conjugaciones: verbos en -a (dirbti: dirbu, dirbi, dirba, dirbame, dirbate, dirba), en -i (mylėti: myliu, myli, myli, mylime, mylite, myli), en -o (kalbėti: kalbu, kalbi, kalba…).\nLa 3.ª persona es igual en singular y plural. Los reflexivos añaden -si (mokytis: mokausi); la negación antepone ne- (nedirbu).", ['Trabajo en Vilna.', 'Él no habla inglés.']),
 'de': ('Das Präsens', "Drei Konjugationen: Verben auf -a (dirbti: dirbu, dirbi, dirba, dirbame, dirbate, dirba), auf -i (mylėti: myliu, myli, myli, mylime, mylite, myli), auf -o (kalbėti: kalbu, kalbi, kalba…).\nDie 3. Person ist im Singular und Plural gleich. Reflexive Verben hängen -si an (mokytis: mokausi); die Verneinung setzt ne- davor (nedirbu).", ['Ich arbeite in Vilnius.', 'Er spricht kein Englisch.']),
 'it': ('Il presente', "Tre coniugazioni: verbi in -a (dirbti: dirbu, dirbi, dirba, dirbame, dirbate, dirba), in -i (mylėti: myliu, myli, myli, mylime, mylite, myli), in -o (kalbėti: kalbu, kalbi, kalba…).\nLa 3ª persona è uguale al singolare e al plurale. I riflessivi aggiungono -si (mokytis: mokausi); la negazione prefissa ne- (nedirbu).", ['Lavoro a Vilnius.', "Lui non parla inglese."]),
 'pt': ('O presente', "Três conjugações: verbos em -a (dirbti: dirbu, dirbi, dirba, dirbame, dirbate, dirba), em -i (mylėti: myliu, myli, myli, mylime, mylite, myli), em -o (kalbėti: kalbu, kalbi, kalba…).\nA 3ª pessoa é igual no singular e no plural. Os reflexivos acrescentam -si (mokytis: mokausi); a negação antepõe ne- (nedirbu).", ['Trabalho em Vilnius.', 'Ele não fala inglês.']),
 'ja': ('現在形', "活用は三種類：-a 型（dirbti：dirbu, dirbi, dirba, dirbame, dirbate, dirba）、-i 型（mylėti：myliu, myli, myli, mylime, mylite, myli）、-o 型（kalbėti：kalbu, kalbi, kalba…）。\n3人称は単数と複数で同じ形です。再帰動詞は -si をつけます（mokytis：mokausi）。否定は ne- を前につけます（nedirbu）。", ['私はヴィリニュスで働いています。', '彼は英語を話しません。']),
 'zh': ('现在时', "三种变位：-a 类（dirbti：dirbu, dirbi, dirba, dirbame, dirbate, dirba），-i 类（mylėti：myliu, myli, myli, mylime, mylite, myli），-o 类（kalbėti：kalbu, kalbi, kalba…）。\n第三人称单复数形式相同。反身动词加 -si（mokytis：mokausi）；否定在前面加 ne-（nedirbu）。", ['我在维尔纽斯工作。', '他不会说英语。']),
 'ko': ('현재 시제', "활용은 세 가지입니다: -a형(dirbti: dirbu, dirbi, dirba, dirbame, dirbate, dirba), -i형(mylėti: myliu, myli, myli, mylime, mylite, myli), -o형(kalbėti: kalbu, kalbi, kalba…).\n3인칭은 단수와 복수가 같습니다. 재귀동사는 -si를 붙이고(mokytis: mokausi), 부정은 앞에 ne-를 붙입니다(nedirbu).", ['저는 빌뉴스에서 일해요.', '그는 영어를 못해요.']),
 'tl': ('Ang kasalukuyan', "Tatlong banghay: pandiwang -a (dirbti: dirbu, dirbi, dirba, dirbame, dirbate, dirba), -i (mylėti: myliu, myli, myli, mylime, mylite, myli), -o (kalbėti: kalbu, kalbi, kalba…).\nPareho ang ikatlong panauhan sa isahan at maramihan. Nagdaragdag ng -si ang mga repleksibo (mokytis: mokausi); inuunahan ng ne- ang negatibo (nedirbu).", ['Nagtatrabaho ako sa Vilnius.', 'Hindi siya nagsasalita ng Ingles.']),
},
'negation-questions': {
 'es': ('Negación y preguntas', "Negación: ne- pegado al verbo (nežinau), y la doble negación es obligatoria: Aš nieko nematau (no veo nada), niekada, niekur, niekas.\nPregunta de sí o no: la partícula ar al principio (Ar tu kalbi lietuviškai?). Interrogativos: kas (quién, qué), kur (dónde), kada (cuándo), kaip (cómo), kodėl (por qué), kiek (cuánto), koks (qué tipo de).", ['¿Hablas inglés?', '¿Dónde vives?']),
 'de': ('Verneinung und Fragen', "Verneinung: ne- am Verb (nežinau), doppelte Verneinung ist Pflicht: Aš nieko nematau (ich sehe nichts), niekada, niekur, niekas.\nJa/Nein-Frage: die Partikel ar am Anfang (Ar tu kalbi lietuviškai?). Fragewörter: kas (wer, was), kur (wo), kada (wann), kaip (wie), kodėl (warum), kiek (wie viel), koks (was für ein).", ['Sprichst du Englisch?', 'Wo wohnst du?']),
 'it': ('Negazione e domande', "Negazione: ne- attaccato al verbo (nežinau), e la doppia negazione è obbligatoria: Aš nieko nematau (non vedo niente), niekada, niekur, niekas.\nDomanda sì/no: la particella ar all'inizio (Ar tu kalbi lietuviškai?). Interrogativi: kas (chi, che cosa), kur (dove), kada (quando), kaip (come), kodėl (perché), kiek (quanto), koks (che tipo di).", ['Parli inglese?', 'Dove abiti?']),
 'pt': ('Negação e perguntas', "Negação: ne- colado ao verbo (nežinau), e a dupla negação é obrigatória: Aš nieko nematau (não vejo nada), niekada, niekur, niekas.\nPergunta de sim ou não: a partícula ar no início (Ar tu kalbi lietuviškai?). Interrogativos: kas (quem, o quê), kur (onde), kada (quando), kaip (como), kodėl (por quê), kiek (quanto), koks (que tipo de).", ['Você fala inglês?', 'Onde você mora?']),
 'ja': ('否定と疑問', "否定：動詞に ne- をつけます（nežinau）。二重否定が必須です：Aš nieko nematau（何も見えない）、niekada、niekur、niekas。\nはい・いいえの疑問：文頭に助詞 ar（Ar tu kalbi lietuviškai?）。疑問詞：kas（誰・何）、kur（どこ）、kada（いつ）、kaip（どう）、kodėl（なぜ）、kiek（いくつ）、koks（どんな）。", ['英語を話せますか？', 'どこに住んでいますか？']),
 'zh': ('否定与疑问', "否定：ne- 直接加在动词前（nežinau），必须使用双重否定：Aš nieko nematau（我什么也没看见），niekada，niekur，niekas。\n是非疑问：句首用助词 ar（Ar tu kalbi lietuviškai?）。疑问词：kas（谁、什么），kur（哪里），kada（什么时候），kaip（怎么），kodėl（为什么），kiek（多少），koks（什么样的）。", ['你会说英语吗？', '你住在哪里？']),
 'ko': ('부정과 의문', "부정: 동사 앞에 ne-를 붙입니다(nežinau). 이중 부정이 필수입니다: Aš nieko nematau(나는 아무것도 안 보여), niekada, niekur, niekas.\n예/아니요 의문: 문장 앞에 소사 ar(Ar tu kalbi lietuviškai?). 의문사: kas(누구, 무엇), kur(어디), kada(언제), kaip(어떻게), kodėl(왜), kiek(얼마나), koks(어떤).", ['영어 할 줄 알아?', '어디 살아?']),
 'tl': ('Negatibo at tanong', "Negatibo: ne- na nakadikit sa pandiwa (nežinau), at sapilitan ang dobleng negatibo: Aš nieko nematau (wala akong nakikita), niekada, niekur, niekas.\nTanong na oo o hindi: partikulang ar sa unahan (Ar tu kalbi lietuviškai?). Pananong: kas (sino, ano), kur (saan), kada (kailan), kaip (paano), kodėl (bakit), kiek (ilan), koks (anong uri).", ['Marunong ka bang mag-Ingles?', 'Saan ka nakatira?']),
},
'adjectifs': {
 'es': ('El adjetivo y los pronombres', "El adjetivo concuerda con el sustantivo en género, número y caso: geras vyras, gera moteris, geri žmonės. Va delante del sustantivo.\nPronombres personales: aš, tu, jis / ji, mes, jūs, jie / jos. Posesivos: mano, tavo, jo, jos, mūsų, jūsų, jų (no concuerdan); savo (reflexivo: el propio).\nDemostrativos: šis / ši (este), tas / ta (ese).", ['Este es mi amigo.']),
 'de': ('Adjektiv und Pronomen', "Das Adjektiv stimmt in Genus, Numerus und Kasus mit dem Nomen überein: geras vyras, gera moteris, geri žmonės. Es steht vor dem Nomen.\nPersonalpronomen: aš, tu, jis / ji, mes, jūs, jie / jos. Possessiva: mano, tavo, jo, jos, mūsų, jūsų, jų (unveränderlich); savo (reflexiv: sein eigener).\nDemonstrativa: šis / ši (dieser), tas / ta (jener).", ['Das ist mein Freund.']),
 'it': ("L'aggettivo e i pronomi", "L'aggettivo concorda con il nome in genere, numero e caso: geras vyras, gera moteris, geri žmonės. Precede il nome.\nPronomi personali: aš, tu, jis / ji, mes, jūs, jie / jos. Possessivi: mano, tavo, jo, jos, mūsų, jūsų, jų (invariabili); savo (riflessivo: il proprio).\nDimostrativi: šis / ši (questo), tas / ta (quello).", ['Questo è il mio amico.']),
 'pt': ('O adjetivo e os pronomes', "O adjetivo concorda com o substantivo em gênero, número e caso: geras vyras, gera moteris, geri žmonės. Vem antes do substantivo.\nPronomes pessoais: aš, tu, jis / ji, mes, jūs, jie / jos. Possessivos: mano, tavo, jo, jos, mūsų, jūsų, jų (invariáveis); savo (reflexivo: o próprio).\nDemonstrativos: šis / ši (este), tas / ta (esse).", ['Este é meu amigo.']),
 'ja': ('形容詞と代名詞', "形容詞は名詞と性・数・格を一致させます：geras vyras、gera moteris、geri žmonės。名詞の前に置きます。\n人称代名詞：aš, tu, jis / ji, mes, jūs, jie / jos。所有：mano, tavo, jo, jos, mūsų, jūsų, jų（変化しません）、savo（再帰：自分の）。\n指示詞：šis / ši（この）、tas / ta（その）。", ['これは私の友達です。']),
 'zh': ('形容词与代词', "形容词与名词在性、数、格上一致：geras vyras，gera moteris，geri žmonės。形容词放在名词前。\n人称代词：aš, tu, jis / ji, mes, jūs, jie / jos。物主代词：mano, tavo, jo, jos, mūsų, jūsų, jų（不变化）；savo（反身：自己的）。\n指示词：šis / ši（这个），tas / ta（那个）。", ['这是我的朋友。']),
 'ko': ('형용사와 대명사', "형용사는 명사와 성·수·격이 일치합니다: geras vyras, gera moteris, geri žmonės. 명사 앞에 옵니다.\n인칭대명사: aš, tu, jis / ji, mes, jūs, jie / jos. 소유: mano, tavo, jo, jos, mūsų, jūsų, jų(변하지 않음), savo(재귀: 자기의).\n지시사: šis / ši(이), tas / ta(그).", ['이 사람은 제 친구예요.']),
 'tl': ('Ang pang-uri at mga panghalip', "Umaayon ang pang-uri sa pangngalan sa kasarian, bilang at kaukulan: geras vyras, gera moteris, geri žmonės. Nauuna ito sa pangngalan.\nPanghalip panao: aš, tu, jis / ji, mes, jūs, jie / jos. Paari: mano, tavo, jo, jos, mūsų, jūsų, jų (hindi nagbabago); savo (repleksibo: sariling).\nPamatlig: šis / ši (ito), tas / ta (iyan).", ['Kaibigan ko ito.']),
},
'pretérit': {
 'es': ('El pasado y el futuro', "Pasado: dirbau, dirbai, dirbo, dirbome, dirbote, dirbo. Pasado frecuentativo (costumbre): dirbdavau. Futuro: dirbsiu, dirbsi, dirbs, dirbsime, dirbsite, dirbs.\nLa 3.ª persona del pasado acaba en -o o -ė (dirbo, kalbėjo).\nUn solo pasado simple para todo hecho terminado.", ['Ayer trabajé en casa.', 'Mañana estaré en Kaunas.']),
 'de': ('Vergangenheit und Zukunft', "Vergangenheit: dirbau, dirbai, dirbo, dirbome, dirbote, dirbo. Gewohnheitsvergangenheit: dirbdavau. Futur: dirbsiu, dirbsi, dirbs, dirbsime, dirbsite, dirbs.\nDie 3. Person der Vergangenheit endet auf -o oder -ė (dirbo, kalbėjo).\nEine einzige einfache Vergangenheit für jedes abgeschlossene Ereignis.", ['Gestern habe ich zu Hause gearbeitet.', 'Morgen bin ich in Kaunas.']),
 'it': ('Il passato e il futuro', "Passato: dirbau, dirbai, dirbo, dirbome, dirbote, dirbo. Passato frequentativo (abitudine): dirbdavau. Futuro: dirbsiu, dirbsi, dirbs, dirbsime, dirbsite, dirbs.\nLa 3ª persona del passato finisce in -o o -ė (dirbo, kalbėjo).\nUn solo passato semplice per ogni fatto concluso.", ['Ieri ho lavorato a casa.', 'Domani sarò a Kaunas.']),
 'pt': ('O passado e o futuro', "Passado: dirbau, dirbai, dirbo, dirbome, dirbote, dirbo. Passado frequentativo (hábito): dirbdavau. Futuro: dirbsiu, dirbsi, dirbs, dirbsime, dirbsite, dirbs.\nA 3ª pessoa do passado termina em -o ou -ė (dirbo, kalbėjo).\nUm só passado simples para todo fato concluído.", ['Ontem trabalhei em casa.', 'Amanhã estarei em Kaunas.']),
 'ja': ('過去と未来', "過去：dirbau, dirbai, dirbo, dirbome, dirbote, dirbo。習慣の過去：dirbdavau。未来：dirbsiu, dirbsi, dirbs, dirbsime, dirbsite, dirbs。\n過去の3人称は -o か -ė で終わります（dirbo, kalbėjo）。\n完了した出来事にはすべて一つの単純過去を使います。", ['昨日は家で働きました。', '明日はカウナスにいます。']),
 'zh': ('过去时与将来时', "过去时：dirbau, dirbai, dirbo, dirbome, dirbote, dirbo。惯常过去时：dirbdavau。将来时：dirbsiu, dirbsi, dirbs, dirbsime, dirbsite, dirbs。\n过去时第三人称以 -o 或 -ė 结尾（dirbo, kalbėjo）。\n所有已完成的事都用同一个简单过去时。", ['昨天我在家工作。', '明天我会在考纳斯。']),
 'ko': ('과거와 미래', "과거: dirbau, dirbai, dirbo, dirbome, dirbote, dirbo. 습관 과거: dirbdavau. 미래: dirbsiu, dirbsi, dirbs, dirbsime, dirbsite, dirbs.\n과거 3인칭은 -o나 -ė로 끝납니다(dirbo, kalbėjo).\n끝난 일에는 모두 하나의 단순 과거를 씁니다.", ['어제 집에서 일했어요.', '내일은 카우나스에 있을 거예요.']),
 'tl': ('Nakaraan at hinaharap', "Nakaraan: dirbau, dirbai, dirbo, dirbome, dirbote, dirbo. Nakagawiang nakaraan: dirbdavau. Hinaharap: dirbsiu, dirbsi, dirbs, dirbsime, dirbsite, dirbs.\nNagtatapos sa -o o -ė ang ikatlong panauhan ng nakaraan (dirbo, kalbėjo).\nIisang payak na nakaraan para sa lahat ng tapos na pangyayari.", ['Nagtrabaho ako sa bahay kahapon.', 'Nasa Kaunas ako bukas.']),
},
'prepositions': {
 'es': ('Las preposiciones y los casos', "Cada preposición rige un caso: į + acusativo (dirección: einu į mokyklą), iš + genitivo (origen: iš Prancūzijos), su + instrumental (con: su draugu), be + genitivo (sin), apie + acusativo (sobre, acerca de), prie + genitivo (junto a), po + genitivo (después de).\nLugar: el locativo sin preposición (Vilniuje, namuose) o ant (sobre), po (debajo), prie, šalia (al lado).", ['Voy a la escuela.', 'Vivo con mi familia.']),
 'de': ('Präpositionen und Fälle', "Jede Präposition regiert einen Fall: į + Akkusativ (Richtung: einu į mokyklą), iš + Genitiv (Herkunft: iš Prancūzijos), su + Instrumental (mit: su draugu), be + Genitiv (ohne), apie + Akkusativ (über), prie + Genitiv (bei), po + Genitiv (nach).\nOrt: der Lokativ ohne Präposition (Vilniuje, namuose) oder ant (auf), po (unter), prie, šalia (neben).", ['Ich gehe zur Schule.', 'Ich wohne mit meiner Familie.']),
 'it': ('Le preposizioni e i casi', "Ogni preposizione regge un caso: į + accusativo (direzione: einu į mokyklą), iš + genitivo (provenienza: iš Prancūzijos), su + strumentale (con: su draugu), be + genitivo (senza), apie + accusativo (su, riguardo a), prie + genitivo (presso), po + genitivo (dopo).\nLuogo: il locativo senza preposizione (Vilniuje, namuose) o ant (sopra), po (sotto), prie, šalia (accanto).", ['Vado a scuola.', 'Vivo con la mia famiglia.']),
 'pt': ('As preposições e os casos', "Cada preposição rege um caso: į + acusativo (direção: einu į mokyklą), iš + genitivo (origem: iš Prancūzijos), su + instrumental (com: su draugu), be + genitivo (sem), apie + acusativo (sobre), prie + genitivo (junto de), po + genitivo (depois de).\nLugar: o locativo sem preposição (Vilniuje, namuose) ou ant (sobre), po (debaixo), prie, šalia (ao lado).", ['Vou à escola.', 'Moro com minha família.']),
 'ja': ('前置詞と格', "前置詞ごとに支配する格が決まっています：į + 対格（方向：einu į mokyklą）、iš + 属格（起点：iš Prancūzijos）、su + 具格（〜と一緒に：su draugu）、be + 属格（〜なしで）、apie + 対格（〜について）、prie + 属格（〜のそばに）、po + 属格（〜の後で）。\n場所：前置詞なしの処格（Vilniuje, namuose）、または ant（〜の上）、po（〜の下）、prie、šalia（〜の隣）。", ['学校に行きます。', '家族と住んでいます。']),
 'zh': ('介词与格', "每个介词支配一个格：į + 宾格（方向：einu į mokyklą），iš + 属格（来源：iš Prancūzijos），su + 工具格（和：su draugu），be + 属格（没有），apie + 宾格（关于），prie + 属格（在……旁），po + 属格（在……之后）。\n地点：不带介词的位格（Vilniuje, namuose），或 ant（在……上），po（在……下），prie，šalia（在……旁边）。", ['我去学校。', '我和家人住在一起。']),
 'ko': ('전치사와 격', "전치사마다 요구하는 격이 정해져 있습니다: į + 대격(방향: einu į mokyklą), iš + 속격(출발: iš Prancūzijos), su + 도구격(~와 함께: su draugu), be + 속격(~없이), apie + 대격(~에 대해), prie + 속격(~ 옆에), po + 속격(~ 후에).\n장소: 전치사 없는 처격(Vilniuje, namuose) 또는 ant(~ 위에), po(~ 아래에), prie, šalia(~ 옆에).", ['학교에 가요.', '가족과 함께 살아요.']),
 'tl': ('Mga pang-ukol at kaukulan', "Bawat pang-ukol ay may kaukulang hinihingi: į + akusatibo (direksiyon: einu į mokyklą), iš + henitibo (pinagmulan: iš Prancūzijos), su + instrumental (kasama: su draugu), be + henitibo (wala), apie + akusatibo (tungkol sa), prie + henitibo (malapit sa), po + henitibo (pagkatapos ng).\nLugar: lokatibo nang walang pang-ukol (Vilniuje, namuose) o ant (ibabaw), po (ilalim), prie, šalia (tabi).", ['Pupunta ako sa paaralan.', 'Nakatira ako kasama ng pamilya ko.']),
},
'conditionnel-imperatif': {
 'es': ('El condicional y el imperativo', "Condicional: raíz del infinitivo + čiau, tum, tų, tumėme, tumėte, tų (dirbčiau, dirbtum, dirbtų). Cortesía: Norėčiau kavos.\nImperativo: dirbk (tú), dirbkime, dirbkite; 3.ª persona con te-: tedirba.\nDeseo: kad + condicional (Noriu, kad tu ateitum).", ['Querría un vaso de agua.']),
 'de': ('Konditional und Imperativ', "Konditional: Infinitivstamm + čiau, tum, tų, tumėme, tumėte, tų (dirbčiau, dirbtum, dirbtų). Höflichkeit: Norėčiau kavos.\nImperativ: dirbk (du), dirbkime, dirbkite; 3. Person mit te-: tedirba.\nWunsch: kad + Konditional (Noriu, kad tu ateitum).", ['Ich hätte gern ein Glas Wasser.']),
 'it': ('Il condizionale e l\'imperativo', "Condizionale: radice dell'infinito + čiau, tum, tų, tumėme, tumėte, tų (dirbčiau, dirbtum, dirbtų). Cortesia: Norėčiau kavos.\nImperativo: dirbk (tu), dirbkime, dirbkite; 3ª persona con te-: tedirba.\nDesiderio: kad + condizionale (Noriu, kad tu ateitum).", ["Vorrei un bicchiere d'acqua."]),
 'pt': ('O condicional e o imperativo', "Condicional: radical do infinitivo + čiau, tum, tų, tumėme, tumėte, tų (dirbčiau, dirbtum, dirbtų). Cortesia: Norėčiau kavos.\nImperativo: dirbk (tu), dirbkime, dirbkite; 3ª pessoa com te-: tedirba.\nDesejo: kad + condicional (Noriu, kad tu ateitum).", ['Eu queria um copo de água.']),
 'ja': ('条件法と命令法', "条件法：不定詞の語幹 + čiau, tum, tų, tumėme, tumėte, tų（dirbčiau, dirbtum, dirbtų）。丁寧な言い方：Norėčiau kavos。\n命令法：dirbk（君）、dirbkime、dirbkite。3人称は te-：tedirba。\n願望：kad + 条件法（Noriu, kad tu ateitum）。", ['水を一杯いただきたいのですが。']),
 'zh': ('条件式与命令式', "条件式：不定式词干 + čiau, tum, tų, tumėme, tumėte, tų（dirbčiau, dirbtum, dirbtų）。礼貌：Norėčiau kavos。\n命令式：dirbk（你），dirbkime，dirbkite；第三人称用 te-：tedirba。\n愿望：kad + 条件式（Noriu, kad tu ateitum）。", ['我想要一杯水。']),
 'ko': ('조건법과 명령법', "조건법: 부정사 어간 + čiau, tum, tų, tumėme, tumėte, tų(dirbčiau, dirbtum, dirbtų). 공손한 표현: Norėčiau kavos.\n명령법: dirbk(너), dirbkime, dirbkite; 3인칭은 te-: tedirba.\n바람: kad + 조건법(Noriu, kad tu ateitum).", ['물 한 잔 주시겠어요?']),
 'tl': ('Kondisyonal at pautos', "Kondisyonal: ugat ng pawatas + čiau, tum, tų, tumėme, tumėte, tų (dirbčiau, dirbtum, dirbtų). Paggalang: Norėčiau kavos.\nPautos: dirbk (ikaw), dirbkime, dirbkite; ikatlong panauhan sa te-: tedirba.\nHiling: kad + kondisyonal (Noriu, kad tu ateitum).", ['Gusto ko sana ng isang basong tubig.']),
},
'participes': {
 'es': ('Los participios', "El lituano usa muchos participios en lugar de oraciones subordinadas: activo presente (dirbantis), pasado (dirbęs), futuro (dirbsiantis); pasivo presente (dirbamas), pasado (dirbtas).\nConcuerdan como adjetivos: Dirbantis vyras = el hombre que trabaja. El semiparticipio (dirbdamas, dirbant) expresa una acción simultánea: Eidamas namo, sutikau draugą.", ['Leo un libro escrito.']),
 'de': ('Die Partizipien', "Das Litauische verwendet viele Partizipien statt Nebensätzen: aktiv Präsens (dirbantis), Vergangenheit (dirbęs), Futur (dirbsiantis); passiv Präsens (dirbamas), Vergangenheit (dirbtas).\nSie werden wie Adjektive angeglichen: Dirbantis vyras = der Mann, der arbeitet. Das Halbpartizip (dirbdamas, dirbant) drückt eine gleichzeitige Handlung aus: Eidamas namo, sutikau draugą.", ['Ich lese ein geschriebenes Buch.']),
 'it': ('I participi', "Il lituano usa molti participi al posto delle subordinate: attivo presente (dirbantis), passato (dirbęs), futuro (dirbsiantis); passivo presente (dirbamas), passato (dirbtas).\nConcordano come aggettivi: Dirbantis vyras = l'uomo che lavora. Il semiparticipio (dirbdamas, dirbant) esprime un'azione simultanea: Eidamas namo, sutikau draugą.", ['Leggo un libro scritto.']),
 'pt': ('Os particípios', "O lituano usa muitos particípios em vez de orações subordinadas: ativo presente (dirbantis), passado (dirbęs), futuro (dirbsiantis); passivo presente (dirbamas), passado (dirbtas).\nConcordam como adjetivos: Dirbantis vyras = o homem que trabalha. O semiparticípio (dirbdamas, dirbant) exprime uma ação simultânea: Eidamas namo, sutikau draugą.", ['Leio um livro escrito.']),
 'ja': ('分詞', "リトアニア語は従属節の代わりに分詞をよく使います：能動現在（dirbantis）、過去（dirbęs）、未来（dirbsiantis）、受動現在（dirbamas）、過去（dirbtas）。\n形容詞と同じように一致します：Dirbantis vyras = 働いている男性。半分詞（dirbdamas, dirbant）は同時の動作を表します：Eidamas namo, sutikau draugą（家に帰る途中で友達に会った）。", ['書かれた本を読んでいます。']),
 'zh': ('分词', "立陶宛语常用分词代替从句：主动现在分词（dirbantis），过去分词（dirbęs），将来分词（dirbsiantis）；被动现在分词（dirbamas），过去分词（dirbtas）。\n分词像形容词一样变化：Dirbantis vyras = 正在工作的男人。半分词（dirbdamas, dirbant）表示同时进行的动作：Eidamas namo, sutikau draugą（回家路上我遇见了朋友）。", ['我在读一本写好的书。']),
 'ko': ('분사', "리투아니아어는 종속절 대신 분사를 많이 씁니다: 능동 현재(dirbantis), 과거(dirbęs), 미래(dirbsiantis), 수동 현재(dirbamas), 과거(dirbtas).\n형용사처럼 일치합니다: Dirbantis vyras = 일하는 남자. 반분사(dirbdamas, dirbant)는 동시 동작을 나타냅니다: Eidamas namo, sutikau draugą(집에 가다가 친구를 만났다).", ['쓰인 책을 읽고 있어요.']),
 'tl': ('Ang mga partisipyo', "Maraming partisipyo ang ginagamit ng Lithuanian sa halip na sugnay na pantulong: aktibong kasalukuyan (dirbantis), nakaraan (dirbęs), hinaharap (dirbsiantis); pasibong kasalukuyan (dirbamas), nakaraan (dirbtas).\nUmaayon ang mga ito tulad ng pang-uri: Dirbantis vyras = ang lalaking nagtatrabaho. Ang kalahating partisipyo (dirbdamas, dirbant) ay sabay na kilos: Eidamas namo, sutikau draugą (pauwi ako nang makasalubong ko ang kaibigan).", ['Nagbabasa ako ng nasulat na libro.']),
},
'nombres': {
 'es': ('Los números', "1 vienas (fem. viena), 2 du (dvi), 3 trys, 4 keturi (keturios), 5 penki (penkios), 6 šeši (šešios), 7 septyni, 8 aštuoni, 9 devyni, 10 dešimt, 11 vienuolika, 12 dvylika, 20 dvidešimt, 100 šimtas.\nConcordancia: con 1, el sustantivo va en singular (vienas namas); de 2 a 9, en plural (du namai, trys knygos); con 10 a 20 y las decenas, en genitivo plural (dešimt namų, dvidešimt metų).\nOrdinales: pirmas, antras, trečias, ketvirtas. La hora: Kiek valandų? — Trečia valanda (son las tres).", ['Tengo dos hermanos.', 'Tiene diez años.']),
 'de': ('Die Zahlen', "1 vienas (fem. viena), 2 du (dvi), 3 trys, 4 keturi (keturios), 5 penki (penkios), 6 šeši (šešios), 7 septyni, 8 aštuoni, 9 devyni, 10 dešimt, 11 vienuolika, 12 dvylika, 20 dvidešimt, 100 šimtas.\nAngleichung: mit 1 steht das Nomen im Singular (vienas namas); von 2 bis 9 im Plural (du namai, trys knygos); mit 10 bis 20 und den Zehnern im Genitiv Plural (dešimt namų, dvidešimt metų).\nOrdnungszahlen: pirmas, antras, trečias, ketvirtas. Uhrzeit: Kiek valandų? — Trečia valanda (es ist drei Uhr).", ['Ich habe zwei Brüder.', 'Er ist zehn Jahre alt.']),
 'it': ('I numeri', "1 vienas (femm. viena), 2 du (dvi), 3 trys, 4 keturi (keturios), 5 penki (penkios), 6 šeši (šešios), 7 septyni, 8 aštuoni, 9 devyni, 10 dešimt, 11 vienuolika, 12 dvylika, 20 dvidešimt, 100 šimtas.\nAccordo: con 1 il nome è al singolare (vienas namas); da 2 a 9 al plurale (du namai, trys knygos); con 10–20 e le decine al genitivo plurale (dešimt namų, dvidešimt metų).\nOrdinali: pirmas, antras, trečias, ketvirtas. L'ora: Kiek valandų? — Trečia valanda (sono le tre).", ['Ho due fratelli.', 'Ha dieci anni.']),
 'pt': ('Os números', "1 vienas (fem. viena), 2 du (dvi), 3 trys, 4 keturi (keturios), 5 penki (penkios), 6 šeši (šešios), 7 septyni, 8 aštuoni, 9 devyni, 10 dešimt, 11 vienuolika, 12 dvylika, 20 dvidešimt, 100 šimtas.\nConcordância: com 1, o substantivo fica no singular (vienas namas); de 2 a 9, no plural (du namai, trys knygos); com 10 a 20 e as dezenas, no genitivo plural (dešimt namų, dvidešimt metų).\nOrdinais: pirmas, antras, trečias, ketvirtas. As horas: Kiek valandų? — Trečia valanda (são três horas).", ['Tenho dois irmãos.', 'Ele tem dez anos.']),
 'ja': ('数', "1 vienas（女性 viena）、2 du（dvi）、3 trys、4 keturi（keturios）、5 penki（penkios）、6 šeši（šešios）、7 septyni、8 aštuoni、9 devyni、10 dešimt、11 vienuolika、12 dvylika、20 dvidešimt、100 šimtas。\n名詞の形：1 のときは単数（vienas namas）、2〜9 は複数（du namai, trys knygos）、10〜20 と十の位は複数属格（dešimt namų, dvidešimt metų）。\n序数：pirmas, antras, trečias, ketvirtas。時刻：Kiek valandų? — Trečia valanda（3時です）。", ['兄弟が二人います。', '彼は10歳です。']),
 'zh': ('数字', "1 vienas（阴性 viena），2 du（dvi），3 trys，4 keturi（keturios），5 penki（penkios），6 šeši（šešios），7 septyni，8 aštuoni，9 devyni，10 dešimt，11 vienuolika，12 dvylika，20 dvidešimt，100 šimtas。\n名词形式：1 后用单数（vienas namas）；2 到 9 用复数（du namai, trys knygos）；10 到 20 及整十用复数属格（dešimt namų, dvidešimt metų）。\n序数：pirmas, antras, trečias, ketvirtas。时间：Kiek valandų? — Trečia valanda（三点了）。", ['我有两个兄弟。', '他十岁。']),
 'ko': ('수', "1 vienas(여성 viena), 2 du(dvi), 3 trys, 4 keturi(keturios), 5 penki(penkios), 6 šeši(šešios), 7 septyni, 8 aštuoni, 9 devyni, 10 dešimt, 11 vienuolika, 12 dvylika, 20 dvidešimt, 100 šimtas.\n명사의 형태: 1과는 단수(vienas namas), 2~9와는 복수(du namai, trys knygos), 10~20과 십 단위와는 복수 속격(dešimt namų, dvidešimt metų).\n서수: pirmas, antras, trečias, ketvirtas. 시간: Kiek valandų? — Trečia valanda(세 시예요).", ['저는 형제가 두 명 있어요.', '그는 열 살이에요.']),
 'tl': ('Mga bilang', "1 vienas (pambabae viena), 2 du (dvi), 3 trys, 4 keturi (keturios), 5 penki (penkios), 6 šeši (šešios), 7 septyni, 8 aštuoni, 9 devyni, 10 dešimt, 11 vienuolika, 12 dvylika, 20 dvidešimt, 100 šimtas.\nPagsang-ayon: sa 1 isahan ang pangngalan (vienas namas); 2 hanggang 9 maramihan (du namai, trys knygos); 10 hanggang 20 at ang mga sampuan ay henitibong maramihan (dešimt namų, dvidešimt metų).\nPanunuran: pirmas, antras, trečias, ketvirtas. Oras: Kiek valandų? — Trečia valanda (alas-tres na).", ['May dalawa akong kapatid na lalaki.', 'Sampung taon na siya.']),
},
'declinaisons': {
 'es': ('Las familias de sustantivos', "La terminación del nominativo indica la familia y, por tanto, los demás casos.\nMasculinos: -as (namas → genitivo namo, locativo name, plural namai), -is (brolis → brolio, brolyje, broliai), -ys (arklys → arklio), -us (sūnus → sūnaus).\nFemeninos: -a (knyga → knygos, knygoje, knygos), -ė (gatvė → gatvės, gatvėje, gatvės).\nAcusativo singular: -ą, -į, -ę, -ų según la familia (namą, brolį, knygą, gatvę).\nEl locativo responde a «¿dónde?» sin preposición: Vilniuje, mieste, mokykloje.", ['Vivo en Vilna.', 'El libro está en la escuela.']),
 'de': ('Die Nomenfamilien', "Die Endung im Nominativ zeigt die Familie und damit die anderen Fälle.\nMaskulin: -as (namas → Genitiv namo, Lokativ name, Plural namai), -is (brolis → brolio, brolyje, broliai), -ys (arklys → arklio), -us (sūnus → sūnaus).\nFeminin: -a (knyga → knygos, knygoje, knygos), -ė (gatvė → gatvės, gatvėje, gatvės).\nAkkusativ Singular: -ą, -į, -ę, -ų je nach Familie (namą, brolį, knygą, gatvę).\nDer Lokativ antwortet auf „wo?“ ohne Präposition: Vilniuje, mieste, mokykloje.", ['Ich wohne in Vilnius.', 'Das Buch ist in der Schule.']),
 'it': ('Le famiglie di nomi', "La desinenza del nominativo indica la famiglia e quindi gli altri casi.\nMaschili: -as (namas → genitivo namo, locativo name, plurale namai), -is (brolis → brolio, brolyje, broliai), -ys (arklys → arklio), -us (sūnus → sūnaus).\nFemminili: -a (knyga → knygos, knygoje, knygos), -ė (gatvė → gatvės, gatvėje, gatvės).\nAccusativo singolare: -ą, -į, -ę, -ų secondo la famiglia (namą, brolį, knygą, gatvę).\nIl locativo risponde a «dove?» senza preposizione: Vilniuje, mieste, mokykloje.", ['Abito a Vilnius.', 'Il libro è a scuola.']),
 'pt': ('As famílias de substantivos', "A terminação do nominativo indica a família e, portanto, os outros casos.\nMasculinos: -as (namas → genitivo namo, locativo name, plural namai), -is (brolis → brolio, brolyje, broliai), -ys (arklys → arklio), -us (sūnus → sūnaus).\nFemininos: -a (knyga → knygos, knygoje, knygos), -ė (gatvė → gatvės, gatvėje, gatvės).\nAcusativo singular: -ą, -į, -ę, -ų conforme a família (namą, brolį, knygą, gatvę).\nO locativo responde a «onde?» sem preposição: Vilniuje, mieste, mokykloje.", ['Moro em Vilnius.', 'O livro está na escola.']),
 'ja': ('名詞の型', "主格の語尾で型がわかり、そこからほかの格も決まります。\n男性：-as（namas → 属格 namo、処格 name、複数 namai）、-is（brolis → brolio, brolyje, broliai）、-ys（arklys → arklio）、-us（sūnus → sūnaus）。\n女性：-a（knyga → knygos, knygoje, knygos）、-ė（gatvė → gatvės, gatvėje, gatvės）。\n対格単数：型により -ą, -į, -ę, -ų（namą, brolį, knygą, gatvę）。\n処格は前置詞なしで「どこで？」に答えます：Vilniuje, mieste, mokykloje。", ['ヴィリニュスに住んでいます。', '本は学校にあります。']),
 'zh': ('名词类别', "主格词尾表明名词类别，从而决定其他格。\n阳性：-as（namas → 属格 namo，位格 name，复数 namai），-is（brolis → brolio, brolyje, broliai），-ys（arklys → arklio），-us（sūnus → sūnaus）。\n阴性：-a（knyga → knygos, knygoje, knygos），-ė（gatvė → gatvės, gatvėje, gatvės）。\n单数宾格：依类别为 -ą, -į, -ę, -ų（namą, brolį, knygą, gatvę）。\n位格不用介词，回答「在哪里？」：Vilniuje, mieste, mokykloje。", ['我住在维尔纽斯。', '书在学校里。']),
 'ko': ('명사의 부류', "주격 어미를 보면 부류를 알 수 있고, 그에 따라 다른 격도 정해집니다.\n남성: -as(namas → 속격 namo, 처격 name, 복수 namai), -is(brolis → brolio, brolyje, broliai), -ys(arklys → arklio), -us(sūnus → sūnaus).\n여성: -a(knyga → knygos, knygoje, knygos), -ė(gatvė → gatvės, gatvėje, gatvės).\n단수 대격: 부류에 따라 -ą, -į, -ę, -ų(namą, brolį, knygą, gatvę).\n처격은 전치사 없이 「어디에?」에 답합니다: Vilniuje, mieste, mokykloje.", ['저는 빌뉴스에 살아요.', '책은 학교에 있어요.']),
 'tl': ('Mga uri ng pangngalan', "Ang hulapi ng nominatibo ang nagsasabi ng uri, kaya pati ng ibang kaukulan.\nPanlalaki: -as (namas → henitibo namo, lokatibo name, maramihan namai), -is (brolis → brolio, brolyje, broliai), -ys (arklys → arklio), -us (sūnus → sūnaus).\nPambabae: -a (knyga → knygos, knygoje, knygos), -ė (gatvė → gatvės, gatvėje, gatvės).\nAkusatibong isahan: -ą, -į, -ę, -ų ayon sa uri (namą, brolį, knygą, gatvę).\nSinasagot ng lokatibo ang «saan?» nang walang pang-ukol: Vilniuje, mieste, mokykloje.", ['Nakatira ako sa Vilnius.', 'Nasa paaralan ang libro.']),
},
'genitif': {
 'es': ('El genitivo: posesión, negación, cantidad', "Posesión: el poseedor en genitivo va delante: brolio namas (la casa del hermano), mamos knyga.\nTras una negación, el complemento directo pasa a genitivo: Turiu laiko → Neturiu laiko. Matau namą → Nematau namo. «No hay»: nėra + genitivo (Nėra duonos).\nCantidad: daug, mažai, kiek + genitivo (daug žmonių, puodelis kavos).\nTras be (sin), iš (de, desde dentro), nuo (desde), iki (hasta), prie (junto a), po (después).", ['No tengo tiempo.', 'Aquí hay mucha gente.']),
 'de': ('Der Genitiv: Besitz, Verneinung, Menge', "Besitz: Der Besitzer steht im Genitiv davor: brolio namas (das Haus des Bruders), mamos knyga.\nNach einer Verneinung steht das direkte Objekt im Genitiv: Turiu laiko → Neturiu laiko. Matau namą → Nematau namo. „Es gibt kein“: nėra + Genitiv (Nėra duonos).\nMenge: daug, mažai, kiek + Genitiv (daug žmonių, puodelis kavos).\nNach be (ohne), iš (aus), nuo (seit, von), iki (bis), prie (bei), po (nach).", ['Ich habe keine Zeit.', 'Hier sind viele Leute.']),
 'it': ('Il genitivo: possesso, negazione, quantità', "Possesso: il possessore al genitivo va davanti: brolio namas (la casa del fratello), mamos knyga.\nDopo una negazione il complemento oggetto passa al genitivo: Turiu laiko → Neturiu laiko. Matau namą → Nematau namo. «Non c'è»: nėra + genitivo (Nėra duonos).\nQuantità: daug, mažai, kiek + genitivo (daug žmonių, puodelis kavos).\nDopo be (senza), iš (da, fuori da), nuo (da, da quando), iki (fino a), prie (presso), po (dopo).", ['Non ho tempo.', "C'è molta gente qui."]),
 'pt': ('O genitivo: posse, negação, quantidade', "Posse: o possuidor no genitivo vem antes: brolio namas (a casa do irmão), mamos knyga.\nDepois de uma negação, o objeto direto passa para o genitivo: Turiu laiko → Neturiu laiko. Matau namą → Nematau namo. «Não há»: nėra + genitivo (Nėra duonos).\nQuantidade: daug, mažai, kiek + genitivo (daug žmonių, puodelis kavos).\nDepois de be (sem), iš (de, de dentro de), nuo (desde), iki (até), prie (junto de), po (depois).", ['Não tenho tempo.', 'Tem muita gente aqui.']),
 'ja': ('属格：所有・否定・量', "所有：持ち主を属格にして前に置きます：brolio namas（兄弟の家）、mamos knyga。\n否定文では直接目的語が属格になります：Turiu laiko → Neturiu laiko。Matau namą → Nematau namo。「〜がない」：nėra + 属格（Nėra duonos）。\n量：daug, mažai, kiek + 属格（daug žmonių, puodelis kavos）。\nbe（〜なしで）、iš（〜から）、nuo（〜以来）、iki（〜まで）、prie（〜のそば）、po（〜の後）の後でも属格です。", ['時間がありません。', 'ここには人がたくさんいます。']),
 'zh': ('属格：所属、否定、数量', "所属：所有者用属格放在前面：brolio namas（兄弟的房子），mamos knyga。\n否定之后，直接宾语变成属格：Turiu laiko → Neturiu laiko。Matau namą → Nematau namo。「没有」：nėra + 属格（Nėra duonos）。\n数量：daug, mažai, kiek + 属格（daug žmonių, puodelis kavos）。\n用在 be（没有），iš（从……里），nuo（从……起），iki（直到），prie（在……旁），po（……之后）之后。", ['我没有时间。', '这里人很多。']),
 'ko': ('속격: 소유, 부정, 수량', "소유: 소유자를 속격으로 앞에 둡니다: brolio namas(형의 집), mamos knyga.\n부정문에서는 목적어가 속격이 됩니다: Turiu laiko → Neturiu laiko. Matau namą → Nematau namo. 「~이 없다」: nėra + 속격(Nėra duonos).\n수량: daug, mažai, kiek + 속격(daug žmonių, puodelis kavos).\nbe(~없이), iš(~에서), nuo(~부터), iki(~까지), prie(~ 옆), po(~ 후) 뒤에도 속격을 씁니다.", ['시간이 없어요.', '여기 사람이 많아요.']),
 'tl': ('Ang henitibo: pag-aari, negatibo, dami', "Pag-aari: nauuna ang may-ari sa henitibo: brolio namas (ang bahay ng kapatid), mamos knyga.\nPagkatapos ng negatibo, nagiging henitibo ang tuwirang layon: Turiu laiko → Neturiu laiko. Matau namą → Nematau namo. «Walang»: nėra + henitibo (Nėra duonos).\nDami: daug, mažai, kiek + henitibo (daug žmonių, puodelis kavos).\nPagkatapos ng be (wala), iš (mula sa), nuo (mula noong), iki (hanggang), prie (malapit sa), po (pagkatapos).", ['Wala akong oras.', 'Maraming tao rito.']),
},
'reflexifs': {
 'es': ('Los verbos reflexivos en -si', "La partícula -si se añade al final del verbo: mokytis (aprender, estudiar) → mokausi, mokaisi, mokosi, mokomės, mokotės, mokosi.\nCon un prefijo o una negación se coloca justo después: keltis → atsikelti (levantarse), nesijaudink (no te preocupes).\nMuy frecuentes: vadintis (Kaip tu vadiniesi? — Aš vadinuosi Jonas), jaustis (Kaip jaučiatės?), tikėtis (esperar), juoktis (reír), rengtis (vestirse), džiaugtis (alegrarse).", ['¿Cómo se llama usted?', 'Estoy aprendiendo lituano.']),
 'de': ('Reflexive Verben auf -si', "Die Partikel -si wird ans Verbende gehängt: mokytis (lernen) → mokausi, mokaisi, mokosi, mokomės, mokotės, mokosi.\nMit einer Vorsilbe oder Verneinung rückt sie direkt dahinter: keltis → atsikelti (aufstehen), nesijaudink (mach dir keine Sorgen).\nSehr häufig: vadintis (Kaip tu vadiniesi? — Aš vadinuosi Jonas), jaustis (Kaip jaučiatės?), tikėtis (hoffen), juoktis (lachen), rengtis (sich anziehen), džiaugtis (sich freuen).", ['Wie heißen Sie?', 'Ich lerne Litauisch.']),
 'it': ('I verbi riflessivi in -si', "La particella -si si aggiunge alla fine del verbo: mokytis (imparare, studiare) → mokausi, mokaisi, mokosi, mokomės, mokotės, mokosi.\nCon un prefisso o una negazione si inserisce subito dopo: keltis → atsikelti (alzarsi), nesijaudink (non preoccuparti).\nMolto frequenti: vadintis (Kaip tu vadiniesi? — Aš vadinuosi Jonas), jaustis (Kaip jaučiatės?), tikėtis (sperare), juoktis (ridere), rengtis (vestirsi), džiaugtis (rallegrarsi).", ['Come si chiama?', 'Sto imparando il lituano.']),
 'pt': ('Os verbos reflexivos em -si', "A partícula -si junta-se ao fim do verbo: mokytis (aprender, estudar) → mokausi, mokaisi, mokosi, mokomės, mokotės, mokosi.\nCom um prefixo ou uma negação, entra logo a seguir: keltis → atsikelti (levantar-se), nesijaudink (não se preocupe).\nMuito comuns: vadintis (Kaip tu vadiniesi? — Aš vadinuosi Jonas), jaustis (Kaip jaučiatės?), tikėtis (esperar), juoktis (rir), rengtis (vestir-se), džiaugtis (alegrar-se).", ['Como o senhor se chama?', 'Estou aprendendo lituano.']),
 'ja': ('-si で終わる再帰動詞', "助詞 -si を動詞の最後につけます：mokytis（学ぶ）→ mokausi, mokaisi, mokosi, mokomės, mokotės, mokosi。\n接頭辞や否定があると、そのすぐ後に入ります：keltis → atsikelti（起きる）、nesijaudink（心配しないで）。\nよく使うもの：vadintis（Kaip tu vadiniesi? — Aš vadinuosi Jonas）、jaustis（Kaip jaučiatės?）、tikėtis（期待する）、juoktis（笑う）、rengtis（服を着る）、džiaugtis（喜ぶ）。", ['お名前は何ですか？', 'リトアニア語を勉強しています。']),
 'zh': ('以 -si 结尾的反身动词', "小品词 -si 加在动词末尾：mokytis（学习）→ mokausi, mokaisi, mokosi, mokomės, mokotės, mokosi。\n有前缀或否定时，-si 紧跟其后：keltis → atsikelti（起床），nesijaudink（别担心）。\n很常用：vadintis（Kaip tu vadiniesi? — Aš vadinuosi Jonas），jaustis（Kaip jaučiatės?），tikėtis（希望），juoktis（笑），rengtis（穿衣），džiaugtis（高兴）。", ['您叫什么名字？', '我在学立陶宛语。']),
 'ko': ('-si로 끝나는 재귀동사', "소사 -si를 동사 끝에 붙입니다: mokytis(배우다) → mokausi, mokaisi, mokosi, mokomės, mokotės, mokosi.\n접두사나 부정이 있으면 바로 그 뒤에 들어갑니다: keltis → atsikelti(일어나다), nesijaudink(걱정하지 마).\n자주 쓰는 동사: vadintis(Kaip tu vadiniesi? — Aš vadinuosi Jonas), jaustis(Kaip jaučiatės?), tikėtis(기대하다), juoktis(웃다), rengtis(옷을 입다), džiaugtis(기뻐하다).", ['성함이 어떻게 되세요?', '저는 리투아니아어를 배우고 있어요.']),
 'tl': ('Mga repleksibong pandiwang -si', "Idinadagdag ang partikulang -si sa dulo ng pandiwa: mokytis (mag-aral) → mokausi, mokaisi, mokosi, mokomės, mokotės, mokosi.\nKapag may unlapi o negatibo, sumisingit ito kasunod nila: keltis → atsikelti (bumangon), nesijaudink (huwag kang mag-alala).\nKaraniwan: vadintis (Kaip tu vadiniesi? — Aš vadinuosi Jonas), jaustis (Kaip jaučiatės?), tikėtis (umasa), juoktis (tumawa), rengtis (magbihis), džiaugtis (matuwa).", ['Ano po ang pangalan ninyo?', 'Nag-aaral ako ng Lithuanian.']),
},
'comparaison': {
 'es': ('Comparativo y superlativo', "Comparativo: -esnis (masc.), -esnė (fem.): geras → geresnis, didelis → didesnis, gražus → gražesnis. «Que»: negu, nei, o už + acusativo (Jis vyresnis už mane).\nSuperlativo: -iausias, -iausia: geriausias, didžiausias, gražiausia.\nAdverbios: greitai → greičiau → greičiausiai; gerai → geriau → geriausiai.", ['Vilna es más grande que Kaunas.', 'Es el mejor restaurante.']),
 'de': ('Komparativ und Superlativ', "Komparativ: -esnis (mask.), -esnė (fem.): geras → geresnis, didelis → didesnis, gražus → gražesnis. „Als“: negu, nei oder už + Akkusativ (Jis vyresnis už mane).\nSuperlativ: -iausias, -iausia: geriausias, didžiausias, gražiausia.\nAdverbien: greitai → greičiau → greičiausiai; gerai → geriau → geriausiai.", ['Vilnius ist größer als Kaunas.', 'Das ist das beste Restaurant.']),
 'it': ('Comparativo e superlativo', "Comparativo: -esnis (masch.), -esnė (femm.): geras → geresnis, didelis → didesnis, gražus → gražesnis. «Di / che»: negu, nei, o už + accusativo (Jis vyresnis už mane).\nSuperlativo: -iausias, -iausia: geriausias, didžiausias, gražiausia.\nAvverbi: greitai → greičiau → greičiausiai; gerai → geriau → geriausiai.", ['Vilnius è più grande di Kaunas.', 'È il miglior ristorante.']),
 'pt': ('Comparativo e superlativo', "Comparativo: -esnis (masc.), -esnė (fem.): geras → geresnis, didelis → didesnis, gražus → gražesnis. «Do que»: negu, nei, ou už + acusativo (Jis vyresnis už mane).\nSuperlativo: -iausias, -iausia: geriausias, didžiausias, gražiausia.\nAdvérbios: greitai → greičiau → greičiausiai; gerai → geriau → geriausiai.", ['Vilnius é maior que Kaunas.', 'É o melhor restaurante.']),
 'ja': ('比較級と最上級', "比較級：-esnis（男性）、-esnė（女性）：geras → geresnis、didelis → didesnis、gražus → gražesnis。「〜より」：negu、nei、または už + 対格（Jis vyresnis už mane）。\n最上級：-iausias, -iausia：geriausias, didžiausias, gražiausia。\n副詞：greitai → greičiau → greičiausiai、gerai → geriau → geriausiai。", ['ヴィリニュスはカウナスより大きいです。', 'これが一番いいレストランです。']),
 'zh': ('比较级与最高级', "比较级：-esnis（阳性），-esnė（阴性）：geras → geresnis，didelis → didesnis，gražus → gražesnis。「比」：negu，nei，或 už + 宾格（Jis vyresnis už mane）。\n最高级：-iausias, -iausia：geriausias, didžiausias, gražiausia。\n副词：greitai → greičiau → greičiausiai；gerai → geriau → geriausiai。", ['维尔纽斯比考纳斯大。', '这是最好的餐厅。']),
 'ko': ('비교급과 최상급', "비교급: -esnis(남성), -esnė(여성): geras → geresnis, didelis → didesnis, gražus → gražesnis. 「~보다」: negu, nei 또는 už + 대격(Jis vyresnis už mane).\n최상급: -iausias, -iausia: geriausias, didžiausias, gražiausia.\n부사: greitai → greičiau → greičiausiai, gerai → geriau → geriausiai.", ['빌뉴스는 카우나스보다 커요.', '여기가 제일 좋은 식당이에요.']),
 'tl': ('Pahambing at pasukdol', "Pahambing: -esnis (panlalaki), -esnė (pambabae): geras → geresnis, didelis → didesnis, gražus → gražesnis. «Kaysa»: negu, nei, o už + akusatibo (Jis vyresnis už mane).\nPasukdol: -iausias, -iausia: geriausias, didžiausias, gražiausia.\nPang-abay: greitai → greičiau → greičiausiai; gerai → geriau → geriausiai.", ['Mas malaki ang Vilnius kaysa Kaunas.', 'Ito ang pinakamagaling na restawran.']),
},
'prefixes': {
 'es': ('Los prefijos verbales: dirección y aspecto', "Un prefijo precisa la dirección de un movimiento: eiti (ir a pie) → ateiti (llegar), išeiti (salir), įeiti (entrar), nueiti (ir hasta), pareiti (volver a casa), praeiti (pasar), užeiti (pasar a ver a alguien). Igual con važiuoti (ir en vehículo): atvažiuoti, išvažiuoti.\nTambién marca la acción terminada (aspecto perfectivo): rašyti (escribir, estar escribiendo) → parašyti (terminar de escribir); daryti → padaryti; skaityti → perskaityti; valgyti → pavalgyti.", ['Ya se ha ido.', 'Leí el libro (hasta el final).']),
 'de': ('Verbpräfixe: Richtung und Aspekt', "Ein Präfix gibt die Richtung einer Bewegung an: eiti (zu Fuß gehen) → ateiti (ankommen), išeiti (hinausgehen), įeiti (hineingehen), nueiti (hingehen), pareiti (heimkommen), praeiti (vorbeigehen), užeiti (vorbeischauen). Ebenso mit važiuoti (fahren): atvažiuoti, išvažiuoti.\nEs macht die Handlung auch abgeschlossen (perfektiver Aspekt): rašyti (schreiben, am Schreiben sein) → parašyti (fertig schreiben); daryti → padaryti; skaityti → perskaityti; valgyti → pavalgyti.", ['Er ist schon gegangen.', 'Ich habe das Buch (zu Ende) gelesen.']),
 'it': ('I prefissi verbali: direzione e aspetto', "Un prefisso indica la direzione di un movimento: eiti (andare a piedi) → ateiti (arrivare), išeiti (uscire), įeiti (entrare), nueiti (andare fino a), pareiti (rientrare), praeiti (passare), užeiti (fare un salto da qualcuno). Lo stesso con važiuoti (andare con un veicolo): atvažiuoti, išvažiuoti.\nRende anche l'azione compiuta (aspetto perfettivo): rašyti (scrivere, stare scrivendo) → parašyti (finire di scrivere); daryti → padaryti; skaityti → perskaityti; valgyti → pavalgyti.", ['È già partito.', 'Ho letto il libro (fino alla fine).']),
 'pt': ('Os prefixos verbais: direção e aspecto', "Um prefixo indica a direção de um movimento: eiti (ir a pé) → ateiti (chegar), išeiti (sair), įeiti (entrar), nueiti (ir até), pareiti (voltar para casa), praeiti (passar), užeiti (dar uma passada). O mesmo com važiuoti (ir de veículo): atvažiuoti, išvažiuoti.\nTambém marca a ação concluída (aspecto perfectivo): rašyti (escrever, estar escrevendo) → parašyti (terminar de escrever); daryti → padaryti; skaityti → perskaityti; valgyti → pavalgyti.", ['Ele já foi embora.', 'Li o livro (até o fim).']),
 'ja': ('動詞の接頭辞：方向とアスペクト', "接頭辞は移動の方向を表します：eiti（歩いて行く）→ ateiti（来る・着く）、išeiti（出る）、įeiti（入る）、nueiti（〜まで行く）、pareiti（帰る）、praeiti（通り過ぎる）、užeiti（立ち寄る）。važiuoti（乗り物で行く）も同じ：atvažiuoti, išvažiuoti。\n動作の完了（完了相）も表します：rašyti（書く・書いている）→ parašyti（書き終える）、daryti → padaryti、skaityti → perskaityti、valgyti → pavalgyti。", ['彼はもう出かけました。', 'その本を（最後まで）読みました。']),
 'zh': ('动词前缀：方向与体', "前缀表示移动方向：eiti（步行去）→ ateiti（来到），išeiti（出去），įeiti（进去），nueiti（走到），pareiti（回家），praeiti（经过），užeiti（顺便拜访）。važiuoti（乘车去）同理：atvažiuoti，išvažiuoti。\n前缀也表示动作完成（完成体）：rašyti（写、正在写）→ parašyti（写完）；daryti → padaryti；skaityti → perskaityti；valgyti → pavalgyti。", ['他已经走了。', '我把书读完了。']),
 'ko': ('동사 접두사: 방향과 상', "접두사는 이동 방향을 나타냅니다: eiti(걸어가다) → ateiti(오다), išeiti(나가다), įeiti(들어가다), nueiti(~까지 가다), pareiti(집에 돌아오다), praeiti(지나가다), užeiti(들르다). važiuoti(타고 가다)도 같습니다: atvažiuoti, išvažiuoti.\n동작의 완료(완료상)도 나타냅니다: rašyti(쓰다, 쓰는 중) → parašyti(다 쓰다), daryti → padaryti, skaityti → perskaityti, valgyti → pavalgyti.", ['그는 벌써 나갔어요.', '그 책을 끝까지 읽었어요.']),
 'tl': ('Mga unlapi ng pandiwa: direksiyon at aspekto', "Tinutukoy ng unlapi ang direksiyon ng galaw: eiti (maglakad papunta) → ateiti (dumating), išeiti (lumabas), įeiti (pumasok), nueiti (pumunta hanggang), pareiti (umuwi), praeiti (dumaan), užeiti (dumalaw sandali). Ganito rin sa važiuoti (sumakay papunta): atvažiuoti, išvažiuoti.\nIpinakikita rin nito na tapos ang kilos (perpektibong aspekto): rašyti (sumulat, nagsusulat) → parašyti (matapos sumulat); daryti → padaryti; skaityti → perskaityti; valgyti → pavalgyti.", ['Umalis na siya.', 'Binasa ko ang libro (hanggang dulo).']),
},
}
